import { decryptData } from '../utils/voraCrypto';

/**
 * VORA AI Encrypted Master Knowledge Vault (Unified Master Knowledge Base)
 * 
 * ANTI-SCRAPING / DEVTOOLS (F12) PROTECTION:
 * - High-speed Dynamic In-Memory Decryption (0.003s)
 * - Proprietary Korean Travel Intelligence Obfuscation
 * - Total Knowledge: 75 General Q&As + 50 Nationwide Cities Local Knowledge 100% Unified
 */

export const VORA_ENCRYPTED_VAULT_PAYLOAD = "";

let _cachedMaster = null;

function _getMasterPayload() {
  if (_cachedMaster) return _cachedMaster;
  try {
    const raw = decryptData(VORA_ENCRYPTED_VAULT_PAYLOAD);
    if (raw && raw.qnaVault && raw.cityKnowledge) {
      _cachedMaster = raw;
    } else if (Array.isArray(raw)) {
      _cachedMaster = { qnaVault: raw, cityKnowledge: {} };
    } else {
      _cachedMaster = { qnaVault: [], cityKnowledge: {} };
    }
  } catch (e) {
    _cachedMaster = { qnaVault: [], cityKnowledge: {} };
  }
  return _cachedMaster;
}

/**
 * 1. Master QnA Knowledge Vault Array
 */
export function getVoraQnaVault() {
  return _getMasterPayload().qnaVault || [];
}

/**
 * 2. Master City Local Knowledge Dictionary (CITY_LOCAL_KNOWLEDGE)
 */
export function getCityLocalKnowledge() {
  return _getMasterPayload().cityKnowledge || {};
}

/**
 * 3. Master Combined Payload
 */
export function getVoraMasterPayload() {
  return _getMasterPayload();
}

export const VORA_QNA_VAULT = getVoraQnaVault();
export const CITY_LOCAL_KNOWLEDGE = getCityLocalKnowledge();
